import numpy as np
from autograd import grad

class integrator:
    def __init__(self, lower: float, upper: float, stepsize: float): 
        self.lower = lower
        self.upper = upper
        self.stepsize = stepsize

    def rectangle_left(self, f) -> float:
        result = 0
        x = self.lower
        while x < self.upper:
            result += f(x) * self.stepsize
            x += self.stepsize
