  q3_data = []

  quartiles = [q1_data, q2_data, q3_data]

  for val in sorted_data:
    if val < q1:
      q1_data += [val]
    elif val > q1 and val < q3:
      q2_data += [val]
    elif val > q3:
      q3_data += [val]

