def binary_search(lst: List[int], x: int) -> int:
    low = 0
    high = len(lst) - 1
    result = -1
    while low <= high:
        mid = (high + low) // 2
        if lst[mid] < x:
            low = mid + 1
        elif lst[mid] > x:
            high = mid - 1
        else:
            result = mid
            high = mid - 1
    return result

