    sorted_data = sorted(data)

    if len(sorted_data) % 2 == 0:
        middleNum1 = sorted_data[len(sorted_data)//2]
        middleNum2 = sorted_data[(len(sorted_data)//2)-1]
        return (middleNum1 + middleNum2)/2
    else:
