    def __init__(self) -> None:
        super().__init__()
        self.turn = 0

    def returnMove(self, board: List[List[bool]]) -> Tuple[int, int]:
        self.turn += 1
        if self.turn == 1:
            return (0, 1)
        elif self.turn == 2:
