class Tree:

    @abstractmethod
    def tree_map(self, func):
        pass 

    @abstractmethod
    def tree_filter(self, func, filler):
        pass 

    @abstractmethod
    def tree_andmap(self, func):
        pass 

    @abstractmethod
    def tree_ormap(self, func):
        pass 

