def find_cycles(permutation):

    permutation = [0] + permutation
    cycles = []
    visited = set()

    for i in range(len(permutation)):

        if i not in visited:
            cycle = []
            current = i

            while current not in visited:
                visited.add(current)
                cycle.append(current)
                current = permutation[current]

            if cycle:
                cycles.append(cycle)

    return cycles[1:]

