import re


class HTMLElement:
    def __init__(self, name, content: List[Union[str, 'HTMLElement']], attributes: Dict[str, str]):
        self.name = name
        self.content = content
        self.attributes = attributes

    def __str__(self):
        prelude = f"<{self.name}"
        for key, value in self.attributes.items():
