        """Computes the variance of the data"""
        mean = sum(X) / len(X)
        return sum((x - mean) ** 2 for x in X) / len(X)

    def correlation(self, cov, var_x, var_y):
        """Computes the correlation of the data based on its Var(X). Var(Y) and Cov(X, Y)"""
