                and line[i+2] == "h" and line[i+3] in "aeiouy": #if V+HV
                lineCopy = lineCopy[:i] + "_" + lineCopy[i+1:]
                lineCopy = lineCopy[:i+3] + "_" + lineCopy[i+4:]
    for i in range(len(line)):
