                and line[i+3] == "h" and line[i+4] in "aeiouy": #if VM+HV
                lineCopy = lineCopy[:i] + "_" + lineCopy[i+1:]
                lineCopy = lineCopy[:i+4] + "_" + lineCopy[i+5:]    
