                if score < min_score:
                    min_score = score
                    best_column = move
                beta = min(beta, score)
                if beta <= alpha:
                    break
            return min_score, best_column

    def best_move(self, player: Player, depth=4) -> int:
        """ Returns the best column for the player using Minimax. """
        _, best_column = self.ai(depth, False, player)
        if best_column is None:
